h = h.replace('<button type="button" class="btn sm" data-act="edit"', '<button type="button" class="btn sm" data-act="sum" aria-expanded="' + !!sumOf(c.id).open + '">' + (sumOf(c.id).open ? 'Fermer familier' : '+ Familier') + '</button><button type="button" class="btn sm" data-act="edit"');
