function tipData(key) {
var p = key.split(':'), id = p.slice(1).join(':');
if (p[0] === 'c') {
var c = byId(id);
if (!c) return null;
var e = libFor(c);
return { role: e ? roleOfEntry(e) : (c.kind === 'pj' ? 'PJ' : 'Monstre'), tags: (e ? e.tags : []).concat(c.tags || []), name: c.name, kind: c.kind, ac: c.ac, hp: c.hp + ' / ' + c.max + (c.temp > 0 ? ' (+' + c.temp + ')' : ''), b: c.b, init: c.init, conds: c.conds, notes: e ? e.notes : (c.cid && bMap[c.cid] ? bNotes(bMap[c.cid]) : ''), cnote: c.notes, img: e ? e.img : '' };
}
if (p[0] === 'b') {
var r = bMap[id];
if (!r) return null;
return { name: r.n, kind: 'mj', ac: r.c, hp: r.h + ' PV', b: r.b, conds: [], notes: bNotes(r), cnote: '', img: '' };
}
var l = libById(id);
if (!l) return null;
return { role: roleOfEntry(l), tags: l.tags || [], name: l.name, kind: l.kind, ac: l.ac, hp: l.hp + ' PV', b: l.b, conds: [], notes: l.notes, cnote: '', img: l.img };
}
function tipHTML(t) {
var img = t.img ? '<img alt="" src="' + t.img + '">' : '<span class="ph">' + esc(initials(t.name)) + '</span>';
return '<div class="tip-img">' + img + '</div><div class="tip-body">' +
'<div class="tip-head"><span class="tag ' + t.kind + '">' + esc(t.role || (t.kind === 'pj' ? 'PJ' : 'Monstre')) + '</span><strong>' + esc(t.name) + '</strong></div>' +
((t.tags || []).filter(function (x) { return ROLE_TAGS.indexOf(x) < 0; }).length ? '<div class="tgs">' + tagPills(t.tags, '') + '</div>' : '') +
'<div class="tip-stats"><span>CA <b>' + t.ac + '</b></span><span>PV <b>' + esc(t.hp) + '</b></span><span>Init. <b>' + (t.b == null ? '—' : sgn(t.b)) + '</b></span></div>' +
(t.conds && t.conds.length ? '<div class="tip-chips">' + t.conds.map(function (x) { return '<span title="' + esc(cdesc(x)) + '">' + esc(x) + (cdesc(x) ? ' : <em style="font-style:normal;opacity:.8">' + esc(cdesc(x)) + '</em>' : '') + '</span>'; }).join('') + '</div>' : '') +
(t.notes ? '<p>' + esc(t.notes) + '</p>' : '') +
(t.cnote ? '<p class="muted">Note de combat : ' + esc(t.cnote) + '</p>' : '') + '</div>';
}
function placeTip(x, y) {
var tip = $('tip');
var w = tip.offsetWidth, h = tip.offsetHeight;
var left = x + 20;
if (left + w > window.innerWidth - 8) left = x - w - 20;
if (left < 8) left = Math.max(8, Math.min(window.innerWidth - w - 8, x - w / 2));
var top = y - h / 2;
top = Math.max(8, Math.min(window.innerHeight - h - 8, top));
tip.style.left = left + 'px';
tip.style.top = top + 'px';
}
function showTip(key, x, y) {
var t = tipData(key);
if (!t) { hideTip(); return; }
var tip = $('tip');
tipKey = key;
tip.innerHTML = tipHTML(t);
tip.hidden = false;
placeTip(x, y);
}
function hideTip() { tipKey = null; $('tip').hidden = true; }
function refreshTip() {
if (!tipKey) return;
var t = tipData(tipKey);
if (!t) { hideTip(); return; }
$('tip').innerHTML = tipHTML(t);
}

function showDice(big, det) {
$('diceout').innerHTML = '<span class="big">' + esc(big) + '</span><span class="det">' + esc(det) + '</span>';
dice.unshift(big + ' · ' + det);
dice = dice.slice(0, 6);
$('dhist').innerHTML = dice.slice(1).map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('');
}
function rollDice(sides) {
var n = Math.max(1, Math.min(20, int($('dn').value, 1)));
var m = int($('dm').value, 0);
var rs = [], sum = 0;
for (var i = 0; i < n; i++) { var r = dr(sides); rs.push(r); sum += r; }
var label = n + 'd' + sides + (m ? ' ' + sgn(m) : '');
var extra = '';
if (sides === 20 && n === 1) extra = rs[0] === 20 ? ' · Critique !' : rs[0] === 1 ? ' · Échec critique' : '';
showDice(String(sum + m), label + ' [' + rs.join(', ') + ']' + extra);
}
function rollAdv(adv) {
var m = int($('dm').value, 0);
var a = dr(20), b = dr(20), pick = adv ? Math.max(a, b) : Math.min(a, b);
var extra = pick === 20 ? ' · Critique !' : pick === 1 ? ' · Échec critique' : '';
showDice(String(pick + m), 'd20 ' + (adv ? 'avantage' : 'désavantage') + (m ? ' ' + sgn(m) : '') + ' [' + a + ', ' + b + ']' + extra);
}

