function shsGet(sh, path) { var p = path.split('.'), o = sh, i; for (i = 0; i < p.length && o != null; i++) o = o[p[i]]; return o == null ? '' : o; }
function shsSet(sh, path, val) {
var p = path.split('.'), o = sh, i;
for (i = 0; i < p.length - 1; i++) { if (!o[p[i]] || typeof o[p[i]] !== 'object') o[p[i]] = {}; o = o[p[i]]; }
if (val === '' || val == null) delete o[p[p.length - 1]]; else o[p[p.length - 1]] = val;
for (i = p.length - 1; i > 0; i--) { var par = sh; for (var j = 0; j < i - 1; j++) par = par[p[j]]; if (par[p[i - 1]] && !Object.keys(par[p[i - 1]]).length) delete par[p[i - 1]]; }
}
function shsF(attr, path, label, sh, o) {
o = o || {};
var v = shsGet(sh, path);
if (o.ta) return '<label class="shf shw"><span>' + label + '</span><textarea ' + attr + '="' + path + '" rows="' + (o.rows || 3) + '" maxlength="2000"' + (o.ph ? ' placeholder="' + esc(o.ph) + '"' : '') + '>' + esc(v) + '</textarea></label>';
return '<label class="shf"><span>' + label + '</span><input type="' + (o.num ? 'number' : 'text') + '" ' + attr + '="' + path + '" maxlength="120" value="' + esc(v) + '"' + (o.ph ? ' placeholder="' + esc(o.ph) + '"' : '') + '></label>';
}
