function normItem(x, id) {
return { id: String(id), name: String(x.name || 'Sans nom'), icat: String(x.icat || 'Divers'), rarity: String(x.rarity || 'Commun'), rraw: String(x.rarity || ''), attune: !!x.attune, bonus: String(x.bonus || ''), dmg: String(x.dmg || ''), value: String(x.value || ''), desc: String(x.desc || ''), img: typeof x.img === 'string' && IMG_RE.test(x.img) ? x.img : '' };
}
function sortItems() { items.sort(function (a, b) { return a.name.localeCompare(b.name, 'fr'); }); miLibDirty(); }
function loadLocalItems() {
try { var r = localStorage.getItem(ITEMS_LS); items = r ? JSON.parse(r).map(function (x) { return normItem(x, x.id || uid()); }) : []; } catch (e) { items = []; }
sortItems();
}
function itemSave(e) {
var body = { name: e.name, icat: e.icat, rarity: e.rarity, attune: e.attune, bonus: e.bonus, dmg: e.dmg, value: e.value, desc: e.desc, img: e.img };
if (itemsCol) { itemsCol.doc(e.id).set(body).catch(function () { cMsg = 'Enregistrement impossible, réessaie.'; renderCreateForm(); }); }
else {
var f = false;
for (var i = 0; i < items.length; i++) if (items[i].id === e.id) { items[i] = e; f = true; }
if (!f) items.push(e);
sortItems();
try { localStorage.setItem(ITEMS_LS, JSON.stringify(items)); } catch (er) { cMsg = 'Stockage plein.'; }
render();
}
}
function itemDelete(id) {
if (itemsCol) itemsCol.doc(id).delete();
else { items = items.filter(function (x) { return x.id !== id; }); try { localStorage.setItem(ITEMS_LS, JSON.stringify(items)); } catch (e) { /* ignoré */ } miLibDirty(); render(); }
}

