function raceByName(n) { if (n === 'Otterfolk nageur') n = 'Otterfolk pêcheur'; for (var i = 0; i < RACES.length; i++) for (var j = 0; j < RACES[i].o.length; j++) if (RACES[i].o[j].n === n) return RACES[i].o[j]; return null; }
function classByName(n) { for (var i = 0; i < CLASSES.length; i++) if (CLASSES[i].n === n) return CLASSES[i]; return null; }
function mod10(n) { return Math.floor((n - 10) / 2); }
function spByEn(e) { for (var i = 0; i < SP.length; i++) if (SP[i].e === e) return SP[i]; return null; }

function subDef(cn) { return SUBS[cn] || null; }
function sub2Def(cn) { return SUB2[cn] || null; }
function sub2On(d, sub) { return !!d && (!d.if || sub === d.if); }
function hbOk(r, sub2) { return !r.hb || r.hb === sub2; }
function subOptHTML(def, cur) {
if (!def) return '<option value=""></option>';
var names = Object.keys(def.o), known = false;
return '<option value="">— Choisir —</option>' + names.map(function (n) { if (n === cur) known = true; return '<option' + (n === cur ? ' selected' : '') + '>' + esc(n) + '</option>'; }).join('') + (cur && !known ? '<option selected>' + esc(cur) + '</option>' : '');
}

