function baseTraits(cn, lvl) {
var l = BASEF[cn];
if (!l) return '';
return 'Capacités de ' + cn + ' :\n' + l.filter(function (f) { return f[0] <= lvl; }).map(function (f) { return '• niv. ' + f[0] + ' ' + f[1] + ' : ' + f[2]; }).join('\n');
}
function subTraits(cn, lvl, sub, sub2) {
var out = [], d = subDef(cn), d2 = sub2Def(cn);
if (d && sub) {
var fs = d.o[sub];
if (fs) {
if (lvl < d.lv) out.push(d.l + ' : ' + sub + ' (choisie au niveau ' + d.lv + ').');
else out.push(d.l + ' : ' + sub + '.\n' + fs.filter(function (f) { return f[0] <= lvl; }).map(function (f) { return '• niv. ' + f[0] + ' ' + f[1] + (f[2] ? ' : ' + f[2] : ''); }).join('\n'));
}
}
if (d2 && sub2On(d2, sub) && sub2 && d2.o[sub2] != null) out.push(d2.l + ' : ' + sub2 + (lvl < d2.lv ? ' (au niveau ' + d2.lv + ')' : ' — ' + d2.o[sub2]) + '.');
return out.join('\n');
}
function classesFromX(x) {
x = x || {};
if (Array.isArray(x.classes) && x.classes.length) return x.classes.map(function (c) { return { n: String(c.n || ''), lv: Math.max(1, Math.min(20, int(c.lv, 1))), sub: String(c.sub || ''), sub2: String(c.sub2 || '') }; });
return [{ n: String(x.classe || ''), lv: Math.max(1, Math.min(20, int(x.niveau, 5))), sub: String(x.sub || ''), sub2: String(x.sub2 || '') }];
}
function classLine(list) {
return list.filter(function (c) { return c.n; }).map(function (c) { return c.n + ' ' + c.lv + (c.sub || c.sub2 ? ' (' + [c.sub, c.sub2].filter(Boolean).join(', ') + ')' : ''); }).join(' / ');
}
