var h = '<section class="panel"><div class="pbody"><h2 class="cph">' + esc(cpUi('lanceH', 'La lance')) + '</h2><p>Quatre morceaux cachés. <b>' + esc(cpUi('rit', 'Le rituel')) + '</b>' + esc(cpUi('ritD', '')) + ' exige de les réunir tous : il suffit d\'en garder <b>un seul</b> hors des mains du culte pour la bloquer.</p>' +
'<p class="' + (cult >= 4 ? 'hint err' : 'hint') + '"><b>Le culte détient ' + cult + '/4.</b> ' + (cult >= 4 ? esc(cpUi('rit', 'Le rituel')) + ' peut être lancée !' : esc(cpUi('rit', 'Le rituel')) + ' est bloquée.') + '</p>' + cpBar(cult, 4, cult >= 4 ? 'bad' : '');
CPD.lance.forEach(function (l) {
var x = cpS.spear[l.k];
h += '<div class="cppiece ' + (x.st === 'Au culte' ? 'cult' : x.st === 'Détruit' ? 'dead' : '') + '"><h3>' + esc(l.t) + '</h3><p class="hint">' + esc(l.lieu) + '</p><p>' + esc(l.pouv) + '</p><p class="cpsong">« ' + esc(l.ch) + ' »</p>' +
'<div class="cpgrid"><label>Statut<select data-cpc="spSt" data-p="' + l.k + '">' + CPD.lst.map(function (s) { return '<option' + (s === x.st ? ' selected' : '') + '>' + esc(s) + '</option>'; }).join('') + '</select></label>' +
'<label>Note<input type="text" data-cpc="spNote" data-p="' + l.k + '" value="' + esc(x.n) + '"></label></div></div>';
});
